class StackUnderflowError(Exception):
    pass


def _is_number(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def evaluate(input_data):
    stack = []
    words = {}

    def pop():
        if not stack:
            raise StackUnderflowError("Insufficient number of items in stack")
        return stack.pop()

    def run(tokens):
        for token in tokens:
            t = token.upper()
            if _is_number(token):
                stack.append(int(token))
            elif t in words:
                run(words[t])
            elif t == "+":
                b, a = pop(), pop()
                stack.append(a + b)
            elif t == "-":
                b, a = pop(), pop()
                stack.append(a - b)
            elif t == "*":
                b, a = pop(), pop()
                stack.append(a * b)
            elif t == "/":
                b, a = pop(), pop()
                if b == 0:
                    raise ZeroDivisionError("divide by zero")
                stack.append(int(a / b))
            elif t == "DUP":
                stack.append(pop())
            elif t == "DROP":
                pop()
            elif t == "SWAP":
                b, a = pop(), pop()
                stack.append(b)
                stack.append(a)
            elif t == "OVER":
                b = pop()
                if not stack:
                    raise StackUnderflowError(
                        "Insufficient number of items in stack"
                    )
                a = stack[-1]
                stack.append(b)
                stack.append(a)
            else:
                raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.split()
        if tokens and tokens[0] == ":":
            name = tokens[1].upper()
            if _is_number(tokens[1]):
                raise ValueError("illegal operation")
            definition = tokens[2:-1]
            # Expand at definition time so later redefinitions do not
            # change the meaning of previously defined words.
            expanded = []
            for token in definition:
                if _is_number(token):
                    expanded.append(token)
                elif token.upper() in words:
                    expanded.extend(words[token.upper()])
                else:
                    expanded.append(token)
            words[name] = expanded
        else:
            run(tokens)

    return stack

from collections import Counter

VALUES = {r: i for i, r in enumerate("23456789", start=2)}
VALUES.update({"10": 10, "J": 11, "Q": 12, "K": 13, "A": 14})


def _parse(card):
    rank, suit = card[:-1], card[-1]
    return VALUES[rank], suit


def _rank(hand):
    cards = [_parse(c) for c in hand.split()]
    values = sorted((v for v, _ in cards), reverse=True)
    suits = [s for _, s in cards]

    counts = Counter(values)
    groups = sorted(counts.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)
    # groups: (value, multiplicity) sorted by multiplicity then value

    is_flush = len(set(suits)) == 1
    unique = sorted(set(values), reverse=True)
    if unique == [14, 5, 4, 3, 2]:
        straight_high = 5
    elif len(unique) == 5 and unique[0] - unique[4] == 4:
        straight_high = unique[0]
    else:
        straight_high = None

    multiplicities = [m for _, m in groups]
    group_values = [v for v, _ in groups]

    if straight_high is not None and is_flush:
        return (8, [straight_high])
    if multiplicities == [4, 1]:
        return (7, group_values)
    if multiplicities == [3, 2]:
        return (6, group_values)
    if is_flush:
        return (5, values)
    if straight_high is not None:
        return (4, [straight_high])
    if multiplicities == [3, 1, 1]:
        return (3, group_values)
    if multiplicities == [2, 2, 1]:
        return (2, group_values)
    if multiplicities == [2, 1, 1, 1]:
        return (1, group_values)
    return (0, values)


def best_hands(hands):
    ranked = [(hand, _rank(hand)) for hand in hands]
    best = max(rank for _, rank in ranked)
    return [hand for hand, rank in ranked if rank == best]

def can_chain(dominoes):
    if not dominoes:
        return []

    def search(remaining, chain):
        if not remaining:
            if chain[0][0] == chain[-1][1]:
                return chain
            return None
        end = chain[-1][1]
        for i, (a, b) in enumerate(remaining):
            rest = remaining[:i] + remaining[i + 1:]
            if a == end:
                result = search(rest, chain + [(a, b)])
                if result is not None:
                    return result
            if b == end and a != b:
                result = search(rest, chain + [(b, a)])
                if result is not None:
                    return result
        return None

    first = dominoes[0]
    return search(dominoes[1:], [first])

class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 1          # current frame number, 1..10
        self.in_frame = 0       # rolls already made in current frame
        self.first = None       # first roll of current frame
        self.bonus_needed = 0   # bonus rolls after frame 10
        self.bonus_done = 0
        self.finished = False

    def roll(self, pins):
        if self.finished:
            raise ValueError("Cannot roll after game is complete")
        if not isinstance(pins, int) or pins < 0 or pins > 10:
            raise ValueError("Invalid number of pins")

        if self.frame < 10:
            if self.in_frame == 0:
                self.first = pins
                self.rolls.append(pins)
                if pins == 10:
                    self.frame += 1
                    self.in_frame = 0
                else:
                    self.in_frame = 1
            else:
                if self.first + pins > 10:
                    raise ValueError("Two rolls in a frame cannot exceed 10")
                self.rolls.append(pins)
                self.frame += 1
                self.in_frame = 0
                self.first = None
        else:
            # Tenth frame, including bonus rolls
            pos = self.in_frame
            if pos == 0:
                self.rolls.append(pins)
                self.in_frame = 1
                self.first = pins
            elif pos == 1:
                if self.first != 10 and self.first + pins > 10:
                    raise ValueError("Two rolls in a frame cannot exceed 10")
                self.rolls.append(pins)
                if self.first == 10:
                    if pins == 10:
                        self.bonus_needed = 2
                        self.bonus_done = 1
                        self.in_frame = 2
                    else:
                        self.bonus_needed = 2
                        self.bonus_done = 1
                        self.in_frame = 2
                elif self.first + pins == 10:
                    self.bonus_needed = 1
                    self.bonus_done = 0
                    self.in_frame = 2
                else:
                    self.finished = True
            else:
                # bonus rolls
                if self.bonus_done == 0 and self.first == 10:
                    # first bonus after strike
                    if pins > 10:
                        raise ValueError("Invalid number of pins")
                    self.rolls.append(pins)
                    self.bonus_done = 1
                elif self.first == 10 and self.bonus_done == 1:
                    first_bonus = self.rolls[-1]
                    if first_bonus != 10 and first_bonus + pins > 10:
                        raise ValueError("Bonus rolls cannot exceed 10")
                    self.rolls.append(pins)
                    self.finished = True
                else:
                    # spare bonus
                    self.rolls.append(pins)
                    self.finished = True

    def score(self):
        if not self.rolls or not self.finished:
            raise ValueError("Game is not complete")
        total = 0
        i = 0
        for _ in range(10):
            if self.rolls[i] == 10:
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            elif self.rolls[i] + self.rolls[i + 1] == 10:
                total += 10 + self.rolls[i + 2]
                i += 2
            else:
                total += self.rolls[i] + self.rolls[i + 1]
                i += 2
        return total

