import copy


class Zipper:
    def __init__(self, tree, crumbs):
        self.tree = tree
        self.crumbs = crumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(copy.deepcopy(tree), [])

    def value(self):
        return self.tree["value"]

    def set_value(self, value):
        self.tree["value"] = value
        return self

    def left(self):
        if self.tree["left"] is None:
            return None
        return Zipper(self.tree["left"], self.crumbs + [(self.tree, "left")])

    def set_left(self, tree):
        self.tree["left"] = copy.deepcopy(tree)
        return self

    def right(self):
        if self.tree["right"] is None:
            return None
        return Zipper(self.tree["right"], self.crumbs + [(self.tree, "right")])

    def set_right(self, tree):
        self.tree["right"] = copy.deepcopy(tree)
        return self

    def up(self):
        if not self.crumbs:
            return None
        parent, _ = self.crumbs[-1]
        return Zipper(parent, self.crumbs[:-1])

    def to_tree(self):
        zipper = self
        while zipper.crumbs:
            zipper = zipper.up()
        return zipper.tree

from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def _find_path(self, target):
        """Return list of nodes from root to the node with target label."""
        stack = [(self, [self])]
        while stack:
            node, path = stack.pop()
            if node.label == target:
                return path
            for child in node.children:
                stack.append((child, path + [child]))
        return None

    def from_pov(self, from_node):
        path = self._find_path(from_node)
        if path is None:
            raise ValueError("Tree could not be reoriented")

        def clone(node):
            return Tree(node.label, [clone(c) for c in node.children])

        # Start with the new root keeping its children.
        current = clone(path[-1])
        for i in range(len(path) - 2, -1, -1):
            node = path[i]
            child_on_path = path[i + 1]
            children = [
                clone(c) for c in node.children if c is not child_on_path
            ]
            children.append(current)
            current = Tree(node.label, children)
        return current

    def path_to(self, from_node, to_node):
        reoriented = self.from_pov(from_node)
        path = reoriented._find_path(to_node)
        if path is None:
            raise ValueError("No path found")
        return [node.label for node in path]

